std::complex<double> DT::A1A1wWTree(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);
    std::complex<double> MH1 = sqrt(std::complex<double>(MH*MH,-MH*WH));
std::complex<double> MH2 = sqrt(std::complex<double>(MS1*MS1,-MS1*WS1));
std::complex<double> MH1c = sqrt(std::complex<double>(MH*MH,MH*WH));
std::complex<double> MH2c = sqrt(std::complex<double>(MS1*MS1,MS1*WS1));
    return (s*cos(alpha)*((MHSqcomp) - (MS1Sqcomp))*(-4*s*(MW*MW) + 12*(MW*MW*MW*MW) + (s*s))*sin(alpha))/(2.*svev*vev*(-s + (MHSqcomp))*(-s + (MS1Sqcomp))*(MW*MW));
    }



double DT::A1A1WwReal(const double&E3, const double&theta2, const double&theta1, const double&phi, const double&s)
{

double m1=MW;
double m2=MW;
double m3=0;
std::complex<double> MH1 = sqrt(std::complex<double>(MH*MH,-MH*WH));
std::complex<double> MH2 = sqrt(std::complex<double>(MS1*MS1,-MS1*WS1));
std::complex<double> MH1c = sqrt(std::complex<double>(MH*MH,MH*WH));
std::complex<double> MH2c = sqrt(std::complex<double>(MS1*MS1,MS1*WS1));

double v=vev;
double vs=svev;
double m = MW;

double m12 = sqrt(s - 2*E3*sqrt(s));
double lambda = sqrt(1- 4*m*m/(m12*m12));
double pre = 1/(64*pow(2*M_PI,4)) *sqrt(E3*E3)*sin(theta1)*sin(theta2)*lambda;

double k1k2=(-pow(m1,2) - pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s)/2.;
double k1k3=-0.5*((pow(m3,2) - E3*sqrt(s))*(pow(m1,2) - pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s) + sqrt((pow(E3,2) - pow(m3,2))/pow(E3 - sqrt(s),2))*(E3 - sqrt(s))*sqrt(s)*sqrt(pow(m1,4) + pow(-pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s,2) - 2*pow(m1,2)*(pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s))*cos(theta2))/(pow(m3,2) - 2*E3*sqrt(s) + s);
double k2k3=(-((pow(m3,2) - E3*sqrt(s))*(-pow(m1,2) + pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s)) + sqrt((pow(E3,2) - pow(m3,2))/pow(E3 - sqrt(s),2))*(E3 - sqrt(s))*sqrt(s)*sqrt(pow(m1,4) + pow(-pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s,2) - 2*pow(m1,2)*(pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s))*cos(theta2))/(2.*(pow(m3,2) - 2*E3*sqrt(s) + s));

std::complex<double> dipol= (pow(EL,6.)*(MH1 - 1.*MH2)*(MH1 + MH2)*(MH1c - 1.*MH2c)*(MH1c + MH2c)*pow(k1k2 + k1k3 + k2k3 + pow(MW,2.),2.)*pow(v,2.)*((2.*k1k2*k1k3*k2k3*pow(k1k2 + k1k3 + k2k3,2.) + (pow(k1k3,2.) + pow(k2k3,2.))*(-1.*pow(k1k2,2.) - 2.*k1k2*(k1k3 + k2k3) + pow(k1k3 + k2k3,2.))*pow(MW,2.) + 4.*k1k2*k1k3*k2k3*pow(MW,4.) - 2.*(pow(k1k3,2.) + pow(k2k3,2.))*pow(MW,6.))/(pow(k1k3,2.)*pow(k2k3,2.)*pow(2.*k1k2 + 2.*k1k3 + 2.*k2k3 - 1.*pow(MH1,2.) + 2.*pow(MW,2.),1.)*pow(2.*k1k2 + 2.*k1k3 + 2.*k2k3 - 1.*pow(MH1c,2.) + 2.*pow(MW,2.),1.)*pow(2.*k1k2 + 2.*k1k3 + 2.*k2k3 - 1.*pow(MH2,2.) + 2.*pow(MW,2.),1.)*pow(2.*k1k2 + 2.*k1k3 + 2.*k2k3 - 1.*pow(MH2c,2.) + 2.*pow(MW,2.),1.)*pow(-1. + pow(MW,2.)/pow(MZ,2.),2.)*pow(vs,2.)) - (1.*(pow(k1k2 + k1k3 + k2k3,2.) + 2.*pow(MW,4.))*((2. + (2.*k1k2)/pow(k1k3 + k2k3,1.) - ((k1k3*(2.*k1k2 + k2k3) + (k1k2 + k2k3)*pow(MW,2.))*sqrt(4.*pow(k1k2 + k1k3 + k2k3,2.) - 4.*pow(MW,4.)))/(2.*pow(k1k3,1.)*pow(k1k2 + k1k3 + k2k3,1.)*sqrt(pow(k1k2,2.) + 2.*k1k2*k2k3 + pow(k2k3,2.) - 1.*pow(MW,2.)*(2.*k1k3 + pow(MW,2.)))))/pow(k1k3,1.) + (2. + (2.*k1k2)/pow(k1k3 + k2k3,1.) - (((2.*k1k2 + k1k3)*k2k3 + (k1k2 + k1k3)*pow(MW,2.))*sqrt(4.*pow(k1k2 + k1k3 + k2k3,2.) - 4.*pow(MW,4.)))/(2.*pow(k2k3,1.)*pow(k1k2 + k1k3 + k2k3,1.)*sqrt(pow(k1k2,2.) + 2.*k1k2*k1k3 + pow(k1k3,2.) - 1.*pow(MW,2.)*(2.*k2k3 + pow(MW,2.)))))/pow(k2k3,1.)))/(pow(-2.*(k1k2 + k1k3 + k2k3) + pow(MH1,2.) - 2.*pow(MW,2.),1.)*pow(-2.*(k1k2 + k1k3 + k2k3) + pow(MH1c,2.) - 2.*pow(MW,2.),1.)*pow(-2.*(k1k2 + k1k3 + k2k3) + pow(MH2,2.) - 2.*pow(MW,2.),1.)*pow(-2.*(k1k2 + k1k3 + k2k3) + pow(MH2c,2.) - 2.*pow(MW,2.),1.)*pow(vs - (1.*pow(MW,2.)*vs)/pow(MZ,2.),2.)))*pow(sin(2.*alpha),2.))/(4.*pow(MW,4.));

return pre*dipol.real();
}



// Conjugate of the tree-level amplitude without polarization sum factors
std::complex<double> DT::A1A1wWTreeConj(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);

    return (s*(MW*MW)*((conj(sqrt(MHSqcomp))*conj(sqrt(MHSqcomp))) - (conj(sqrt(MS1Sqcomp))*conj(sqrt(MS1Sqcomp))))*sin(2*alpha))/(svev*vev*(s - (conj(sqrt(MHSqcomp))*conj(sqrt(MHSqcomp))))*(s - (conj(sqrt(MS1Sqcomp))*conj(sqrt(MS1Sqcomp)))));
    }


inline std::complex<double>
operator+(int lhs, const std::complex<double>& rhs)
{
    return std::complex<double>(static_cast<double>(lhs), 0.0) + rhs;
}
   template <typename T>
std::complex<T> operator*(int lhs, const std::complex<T>& rhs) {
   return static_cast<T>(lhs) * rhs;
}


inline double Csc(double x) {
return 1.0 / sin(x);
}

inline double Sec(double x) {
return 1.0 / cos(x);
}

inline double Cot(double x) {
return std::tan(M_PI_2 - x);
}



